import{_ as e,o,c as d,a2 as a}from"./chunks/framework.C_Knpfj2.js";const u=JSON.parse('{"title":"Code Layout","description":"","frontmatter":{},"headers":[],"relativePath":"contributing/code-layout.md","filePath":"contributing/code-layout.md","lastUpdated":1785825381000}'),r={name:"contributing/code-layout.md"};function s(c,t,i,n,l,h){return o(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="code-layout" tabindex="-1">Code Layout <a class="header-anchor" href="#code-layout" aria-label="Permalink to &quot;Code Layout&quot;">​</a></h1><p>AOSC source lives in a single <code>aosc-plugin/</code> module. Shared code is at <code>src/main/java/com/atlassian/opensearch/aosc/</code>; files that differ between OpenSearch 2.x and 3.x live in <code>src/main/java-2x/</code> and <code>src/main/java-3x/</code>. Gradle selects the matching compat directory based on <code>-PopensearchVersion</code>. The same pattern applies to test source sets (<code>src/{test,itTest,smokeTest,scaleTest,benchmarkTest,yamlRestTest}/</code>). See <a href="./running-tests">Running Tests</a> for the test tiers and <code>opensearch-docker/</code> for the local cluster.</p><h2 id="version-compatibility" tabindex="-1">Version Compatibility <a class="header-anchor" href="#version-compatibility" aria-label="Permalink to &quot;Version Compatibility&quot;">​</a></h2><p>Most code lives in shared source directories (<code>src/*/java/</code>) and compiles against both OpenSearch 2.x and 3.x. Files that use version-specific APIs live in <code>src/*/java-2x/</code> and <code>src/*/java-3x/</code>. Gradle selects the matching compat directory based on <code>-PopensearchVersion</code>.</p><p><strong>When to use shared vs compat dirs:</strong></p><ul><li><strong>Shared</strong> (<code>java/</code>): Default location. Use when the code compiles identically against both versions.</li><li><strong>Compat</strong> (<code>java-2x/</code> + <code>java-3x/</code>): Use when the file must import a type that moved between versions (e.g., <code>org.opensearch.client.Client</code> → <code>org.opensearch.transport.client.Client</code>), or when an API signature changed (e.g., <code>TotalHits.value</code> field → method).</li></ul><p><strong>Compat utilities</strong> abstract the real API differences so most code stays shared:</p><div class="aosc-table-scroll"><table class="aosc-table"><thead><tr><th>Utility</th><th>Location</th><th>What it abstracts</th></tr></thead><tbody><tr><td><code>AsyncClientHelper</code></td><td><code>main/java-{2,3}x</code></td><td>Wraps the version-specific <code>Client</code>; all shared code receives this instead</td></tr><tr><td><code>OsCompat</code></td><td><code>main/java-{2,3}x</code></td><td><code>TotalHits</code> field vs method, <code>storedFields()</code> accessor</td></tr><tr><td><code>OsTestCompat</code></td><td><code>test/java-{2,3}x</code></td><td><code>ShardStats</code> constructor (6 vs 7 params)</td></tr><tr><td><code>MockClientFactory</code></td><td><code>test/java-{2,3}x</code></td><td>Mock <code>Client</code>/<code>AdminClient</code> creation, <code>AcknowledgedResponse</code></td></tr><tr><td><code>HttpCompat</code></td><td><code>smokeTest,benchmarkTest/java-{2,3}x</code></td><td>Apache HttpClient 4 vs 5 packages</td></tr></tbody></table></div><p><strong>Drift guard:</strong> CI runs <code>scripts/check-compat-drift.sh</code> to verify that non-excepted compat file pairs differ only in import/package lines. If you add a real code difference to a compat file, add it to the exceptions list in that script.</p><h2 id="main-packages" tabindex="-1">Main Packages <a class="header-anchor" href="#main-packages" aria-label="Permalink to &quot;Main Packages&quot;">​</a></h2><div class="aosc-table-scroll"><table class="aosc-table"><thead><tr><th>Package</th><th>Responsibility</th></tr></thead><tbody><tr><td><code>action.*</code></td><td>Transport actions and request/response types.</td></tr><tr><td><code>rest.*</code></td><td>REST handlers that parse HTTP requests and call transport actions.</td></tr><tr><td><code>model.*</code></td><td>Migration documents, options, phases, routing mode, and DTOs.</td></tr><tr><td><code>service.coordinator.*</code></td><td>Cluster-manager-side orchestration and cutover.</td></tr><tr><td><code>service.worker.*</code></td><td>Data-node shard workers, backfill, replay, retention leases.</td></tr><tr><td><code>service.bulk.*</code></td><td>Bulk writer pipeline and write controllers.</td></tr><tr><td><code>service.adaptive.*</code></td><td>AIMD and adaptive control helpers.</td></tr><tr><td><code>transform.*</code></td><td>Identity and update-script transform functions.</td></tr><tr><td><code>statemachine.*</code></td><td>Async state-machine framework.</td></tr><tr><td><code>utils.*</code></td><td>Logging, JSON, async, and OpenSearch helper utilities.</td></tr></tbody></table></div><h2 id="key-classes" tabindex="-1">Key Classes <a class="header-anchor" href="#key-classes" aria-label="Permalink to &quot;Key Classes&quot;">​</a></h2><div class="aosc-table-scroll"><table class="aosc-table"><thead><tr><th>Class</th><th>Why it matters</th></tr></thead><tbody><tr><td><code>AoscPlugin</code></td><td>Plugin entry point and component registration.</td></tr><tr><td><code>RestStartMigrationAction</code></td><td><code>POST /_plugins/_aosc/{index}/_start</code>.</td></tr><tr><td><code>TransportStartMigrationAction</code></td><td>Start validation and coordinator handoff.</td></tr><tr><td><code>AoscCoordinatorService</code></td><td>Manages active coordinators on the cluster-manager node.</td></tr><tr><td><code>MigrationCoordinator</code></td><td>Coordinator phase handlers and cutover orchestration.</td></tr><tr><td><code>AoscShardService</code></td><td>Creates and manages shard workers on data nodes.</td></tr><tr><td><code>ShardMigrationWorker</code></td><td>Worker state machine.</td></tr><tr><td><code>BackfillEngine</code></td><td>Reads source documents and emits target index requests.</td></tr><tr><td><code>TranslogReplayEngine</code></td><td>Replays source operation history into the target.</td></tr><tr><td><code>TransformFactory</code></td><td>Builds transform functions from <code>transform_script</code>.</td></tr><tr><td><code>AoscSettings</code></td><td>Cluster setting definitions and defaults.</td></tr></tbody></table></div><h2 id="where-changes-usually-go" tabindex="-1">Where Changes Usually Go <a class="header-anchor" href="#where-changes-usually-go" aria-label="Permalink to &quot;Where Changes Usually Go&quot;">​</a></h2><div class="aosc-table-scroll"><table class="aosc-table"><thead><tr><th>Change</th><th>Likely files</th></tr></thead><tbody><tr><td>New REST endpoint</td><td><code>rest/</code>, <code>action/</code>, REST specs/tests.</td></tr><tr><td>New start option</td><td><code>MigrationRequestOptions</code>, validators, docs, tests.</td></tr><tr><td>Coordinator phase behavior</td><td><code>MigrationCoordinator</code>, <code>CoordinatorPhase</code>, state-machine tests.</td></tr><tr><td>Worker phase behavior</td><td><code>ShardMigrationWorker</code>, <code>ShardPhase</code>, worker tests.</td></tr><tr><td>Backfill or replay behavior</td><td><code>BackfillEngine</code>, <code>TranslogReplayEngine</code>, bulk tests.</td></tr><tr><td>Transform behavior</td><td><code>transform/</code>, <code>TransformFactory</code>, transform tests.</td></tr><tr><td>New setting</td><td><code>AoscSettings</code>, configuration docs, tests.</td></tr></tbody></table></div><h2 id="style-notes" tabindex="-1">Style Notes <a class="header-anchor" href="#style-notes" aria-label="Permalink to &quot;Style Notes&quot;">​</a></h2><ul><li>Use <code>AoscLogger</code> for plugin logging.</li><li>Keep public wire fields stable and documented.</li><li>Prefer existing async <code>ActionListener</code> and <code>CompletableFuture</code> bridging patterns.</li><li>Run Spotless before sending a pull request.</li></ul>',17)])])}const g=e(r,[["render",s]]);export{u as __pageData,g as default};
